mapper.select:
select
*
from b_xiecheng_colliding_data_${tableNameSuffix}
where is_delete = 0
 and retry_count > 0 and retry_count < 3

    and id > #{minId}

order by id asc limit 20000;

select
    *
from b_xiecheng_colliding_data_loop_cycle
where is_delete = 1
     and update_time < #{startTime}
order by update_time asc limit #{size};

mapper.delete:
delete from b_xiecheng_colliding_data_loop_cycle
where id in

    #{id}

limit #{size};

mapper.select:
select
*
from b_xiecheng_colliding_data_${tableNameSuffix}
where is_delete = 0 and retry_count = 3

    and id > #{minId}

order by id asc limit 20000;
